mapper.select:
select *
from monitor_task_instance
where biz_date = #{bizDate}
  and task_code = #{taskCode}
  and run_times = #{runNo}
limit 1

select *
from monitor_task_instance
where biz_date = #{bizDate}
  and task_code = #{taskCode}
order by updated_time desc, id desc
limit 1

mapper.delete:
delete
from monitor_task_instance
where biz_date = #{bizDate}
  and task_code = #{taskCode}
  and id <> #{excludeId}

mapper.select:
select max(run_times)
from monitor_task_instance
where biz_date = #{bizDate}
  and task_code = #{taskCode}

select cast(avg(current_cost_minutes) as signed) from monitor_task_instance where task_code = #{taskCode} and biz_date in
#{bizDate}
and result_status = 'SUCCESS' and current_cost_minutes is not null and current_cost_minutes > 0
